260   \param x the X top-right coordinate, in pixels
   261   \param y the Y top-right coordinate, in pixels
   262   \param w the width in pixels of the area to render
   263   \param h the height in pixels of the area to render
   264   \param rotate the rotation to apply when rendering the page
   265
   266   \returns the rendered image, or a null one in case of errors
   267
   268   \see can_render
   269   */
   270  image page_renderer::render_page(const page *p,
   271                                   double xres, double yres,
   272                                   int x, int y, int w, int h,
   273                                   rotation_enum rotate) const
   274  {
   275      if (!p) {
   276          return image();
   277      }
   278
   279  #if defined(HAVE_SPLASH)
   280      page_private *pp = page_private::get(p);
   281      PDFDoc *pdfdoc = pp->doc->doc;
   282
   283      SplashColorMode colorMode;
   284      SplashThinLineMode lineMode;
   285
   286      if (!d->conv_color_mode(d->image_format, colorMode) ||
   287          !d->conv_line_mode(d->line_mode, lineMode)) {
   288          return image();
   289      }
   290
   291      SplashColor bgColor;
   292      bgColor[0] = d->paper_color & 0xff;
   293      bgColor[1] = (d->paper_color >> 8) & 0xff;
   294      bgColor[2] = (d->paper_color >> 16) & 0xff;
   295      SplashOutputDev splashOutputDev(colorMode, 4, gFalse, bgColor, gTrue, lineMode);
   296      splashOutputDev.setFontAntialias(d->hints & text_antialiasing ? gTrue : gFalse);
   297      splashOutputDev.setVectorAntialias(d->hints & antialiasing ? gTrue : gFalse);
   298      splashOutputDev.setFreeTypeHinting(d->hints & text_hinting ? gTrue : gFalse, gFalse);
   299      splashOutputDev.startDoc(pdfdoc);
   300      pdfdoc->displayPageSlice(&splashOutputDev, pp->index + 1,
   301                               xres, yres, int(rotate) * 90,
   302                               gFalse, gTrue, gFalse,
   303                               x, y, w, h);
   304
   305      SplashBitmap *bitmap = splashOutputDev.getBitmap();
   306      const int bw = bitmap->getWidth();
   307      const int bh = bitmap->getHeight();
   308
   309      SplashColorPtr data_ptr = bitmap->getDataPtr();
   310
   311      const image img(reinterpret_cast<char *>(data_ptr), bw, bh, d->image_format);
   312      return img.copy();
   313  #else
   314      return image();
   315  #endif
